exclusivos:
printf %s '#!/bin/bash
error() { printf "%s\n" "$2" >&2; exit "$1"; }
[[ $# -ne 2 ]] && error 1 '"'"'uso: exclusivos.sh DIRECTORIO1 DIRECTORIO2'"'"'
[[ ! -d $1 || ! -d $2 ]] && error 4 '"'"'el directorio no existe'"'"'
a=${1%/}; b=${2%/}
[[ -z $a ]] && a=/
[[ -z $b ]] && b=/
while IFS= read -r f; do printf '"'"'%s/%s\n'"'"' "${a%/}" "$f"; done < <(comm -23 <(find "$a" -maxdepth 1 -type f -printf '"'"'%f\n'"'"' | sort) <(find "$b" -maxdepth 1 -type f -printf '"'"'%f\n'"'"' | sort))
while IFS= read -r f; do printf '"'"'%s/%s\n'"'"' "${b%/}" "$f"; done < <(comm -13 <(find "$a" -maxdepth 1 -type f -printf '"'"'%f\n'"'"' | sort) <(find "$b" -maxdepth 1 -type f -printf '"'"'%f\n'"'"' | sort))
exit 0
' > /home/learner/aso/p22/exclusivos.sh
chmod 755 /home/learner/aso/p22/exclusivos.sh
chown learner:learner /home/learner/aso/p22/exclusivos.sh
